function response(chatId, text, replyMarkup, session, callbackQueryId = null) {
  return [{ json: { chatId, text, replyMarkup, session, callbackQueryId } }];
}

function responseWithAI(chatId, aiPrompt, replyMarkup, session, callbackQueryId = null) {
  return [{ json: { chatId, useAI: true, aiPrompt, replyMarkup, session, callbackQueryId } }];
}

function normalizeText(text) {
  return String(text || "")
    .trim()
    .toLowerCase()
    .replace(/ي/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/أ|إ|ٱ/g, "ا")
    .replace(/آ/g, "ا")
    .replace(/ۀ/g, "ه")
    .replace(/ة/g, "ه")
    .replace(/‌/g, " ")
    .replace(/[ًٌٍَُِّْ]/g, "")
    .replace(/[^\u0600-\u06FFa-zA-Z0-9\s]/g, " ")
    .replace(/\s+/g, " ");
}

function compactText(text) {
  return normalizeText(text).replace(/\s+/g, "");
}

function productSearchableText(product) {
  return [
    product.name,
    product.category,
    product.shortDescription,
    ...(product.skinTypes || []),
    ...(product.concerns || []),
    ...(product.benefits || []),
    product.usage,
    product.notSuitableFor
  ].join(" ");
}

function productPromptBlock(product) {
  return `
نام: ${product.name}
دسته‌بندی: ${product.category}
قیمت: ${product.price}
موجودی: ${product.stock}
مناسب برای: ${product.skinTypes.join("، ")}
کمک به: ${product.concerns.join("، ")}
توضیح کوتاه: ${product.shortDescription}
ویژگی‌ها: ${product.benefits.join("، ")}
روش مصرف: ${product.usage}
نامناسب برای: ${product.notSuitableFor}
لینک خرید: ${product.buyLink}
`;
}

function findProductById(productId) {
  return PRODUCTS.find(p => p.id === productId);
}

