// ============================================
// Search + AI Prompts
// ============================================

function expandQuery(query) {
  const q = normalizeText(query);
  const compact = compactText(query);
  const synonyms = [];

  if (q.includes("ضد افتاب") || q.includes("ضدافتاب") || q.includes("ضد آفتاب") || q.includes("افتاب") || compact.includes("ضدافتاب")) {
    synonyms.push("ضدآفتاب", "ضد افتاب", "spf", "محافظت روزانه");
  }

  if (q.includes("شوینده") || q.includes("ژل") || q.includes("شستشو") || q.includes("صورت شوی")) {
    synonyms.push("ژل شستشو", "شوینده صورت", "پاکسازی");
  }

  if (q.includes("جوش") || q.includes("اکنه") || q.includes("آکنه")) {
    synonyms.push("جوش", "آکنه", "کنترل جوش", "پوست چرب");
  }

  if (q.includes("لک") || q.includes("تیرگی") || q.includes("روشن")) {
    synonyms.push("لک", "تیرگی", "روشن کننده", "ضدلک");
  }

  if (q.includes("آبرسان") || q.includes("اب رسان") || q.includes("ابرسان") || q.includes("مرطوب") || q.includes("خشکی")) {
    synonyms.push("آبرسان", "مرطوب کننده", "خشکی", "پوست خشک");
  }

  if (q.includes("تونر") || q.includes("منافذ")) {
    synonyms.push("تونر", "منافذ", "پاک کننده منافذ");
  }

  if (q.includes("حساس") || q.includes("قرمزی") || q.includes("التهاب")) {
    synonyms.push("حساس", "قرمزی", "آرام بخش", "پوست حساس");
  }

  return [q, compact, ...synonyms.map(normalizeText), ...synonyms.map(compactText)].filter(Boolean);
}

function scoreProductByQuery(product, query) {
  const queries = expandQuery(query);
  const normalSearchable = normalizeText(productSearchableText(product));
  const compactSearchable = compactText(productSearchableText(product));

  let score = 0;

  for (const q of queries) {
    if (!q || q.length < 2) continue;

    if (normalSearchable.includes(q)) score += 5;
    if (compactSearchable.includes(q)) score += 5;

    const words = normalizeText(q).split(" ").filter(w => w.length >= 2);
    for (const word of words) {
      if (normalSearchable.includes(word)) score += 1;
    }
  }

  return score;
}
function isSearchableBeautyMessage(text) {
  const t = normalizeText(text);
  const c = compactText(text);

  const beautyKeywords = [
    "پوست", "صورت", "صورتم",
    "ضد افتاب", "ضد آفتاب", "ضدافتاب", "افتاب", "spf",
    "آبرسان", "ابرسان", "مرطوب",
    "شوینده", "ژل", "تونر", "سرم", "کرم",
    "جوش", "اکنه", "آکنه",
    "لک", "تیرگی",
    "خشک", "چرب", "حساس", "مختلط",
    "منافذ", "قرمزی", "روتین"
  ];

  return beautyKeywords.some(k => {
    const nk = normalizeText(k);
    const ck = compactText(k);
    return t.includes(nk) || c.includes(ck);
  });
}
function findProductsByQuery(query) {
  if (!isSearchableBeautyMessage(query)) {
    return [];
  }

  return PRODUCTS
    .map(product => ({ product, score: scoreProductByQuery(product, query) }))
    .filter(item => item.score > 0)
    .sort((a, b) => b.score - a.score)
    .map(item => item.product);
}

function findNearestProducts(query, limit = 3) {
  if (!isSearchableBeautyMessage(query)) {
    return [];
  }

  const scored = PRODUCTS
    .map(product => ({ product, score: scoreProductByQuery(product, query) }))
    .sort((a, b) => b.score - a.score);

  const positive = scored.filter(item => item.score > 0).map(item => item.product);
  return positive.length ? positive.slice(0, limit) : [];
}
function buildProductInfoAIPrompt(product, userQuery, isNearest = false) {
  return `
تو مشاور فروش یک فروشگاه محصولات مراقبت پوست هستی.

کاربر این عبارت را نوشته:
"${userQuery}"

${isNearest ? "محصول دقیق با این عبارت در دیتای تستی پیدا نشده. نزدیک‌ترین محصول پیشنهادی این است:" : "محصول پیدا شده:"}

${productPromptBlock(product)}

قواعد پاسخ:
- فارسی، طبیعی، کوتاه و فروشگاهی جواب بده.
- اگر محصول دقیق پیدا نشده، اول خیلی کوتاه بگو «این مورد دقیقاً در لیست تستی نیست، اما نزدیک‌ترین پیشنهاد این محصوله».
- قیمت، موجودی و لینک را دقیقاً از اطلاعات بالا بگو.
- هیچ قیمت، موجودی، لینک، محصول یا ویژگی جدیدی نساز.
- ادعای درمان قطعی نکن.
- اگر مشکل پوستی شدید، دردناک، التهابی، عفونی، طولانی‌مدت یا همراه با زخم بود، توصیه کن با پزشک یا متخصص پوست مشورت کند.
- حداکثر ۷ خط بنویس.
- خروجی فقط متن پیام باشد.
`;
}

