  problem_oiliness: "چربی زیاد پوست",
  problem_sensitive: "قرمزی و حساسیت",
  problem_lines: "خطوط ریز و خشکی دور چشم"
};

const problemKeywordsMap = {
  "جوش و آکنه": ["جوش", "آکنه", "چربی زیاد"],
  "لک و تیرگی": ["لک", "تیرگی", "کدری پوست", "محافظت روزانه"],
  "خشکی پوست": ["خشکی", "کشیدگی پوست", "پوسته‌پوسته شدن"],
  "چربی زیاد پوست": ["چربی زیاد", "منافذ باز"],
  "قرمزی و حساسیت": ["قرمزی", "حساسیت", "خشکی"],
  "خطوط ریز و خشکی دور چشم": ["خطوط ریز", "خشکی دور چشم", "خستگی پوست"]
};

function findProductsByProblem(problem) {
  const keywords = problemKeywordsMap[problem] || [problem];

  return PRODUCTS.map(product => {
    const searchable = normalizeText(productSearchableText(product));
    let score = 0;

    for (const keyword of keywords) {
      const k = normalizeText(keyword);
      if (searchable.includes(k)) score += 5;

      const words = k.split(" ").filter(w => w.length >= 2);
      for (const word of words) {
        if (searchable.includes(word)) score += 1;
      }
    }

    return { product, score };
  })
    .filter(item => item.score > 0)
    .sort((a, b) => b.score - a.score)
    .map(item => item.product);
}

function isFreeConsultationMessage(text) {
  const t = normalizeText(text);
