    mainMenuMarkup(),
    s,
    callbackQueryId
  );
}

if (s.step === "WAITING_ORDER_TRACKING") {
  const inputText = msg.replace(/\s+/g, "");

  let foundOrder = store.orders[inputText];

  if (!foundOrder) {
