const orderSteps = [
  "WAITING_ORDER_PRODUCT",
  "WAITING_ORDER_NAME",
  "WAITING_ORDER_PHONE",
  "WAITING_ORDER_ADDRESS",
  "WAITING_ORDER_CONFIRMATION",
  "WAITING_ORDER_TRACKING"
];

const isCallbackCommand =
  msg.startsWith("order_") ||
  msg.startsWith("ask_") ||
  msg.startsWith("skin_") ||
  msg.startsWith("problem_") ||
  msg === "consulting" ||
  msg === "product_info" ||
  msg === "skin_type_advice" ||
  msg === "skin_problem_advice" ||
  msg === "track_order" ||
  msg === "start_order" ||
  msg === "about_demo" ||
  msg === "back_to_main";

// 1) Follow-up question about previous product
if (
  !orderSteps.includes(s.step) &&
  !isCallbackCommand &&
  s.temp?.lastSuggestedProductId &&
  isFollowUpProductQuestion(msg)
) {
  const product = findProductById(s.temp.lastSuggestedProductId);

  if (product) {
    s.step = "CONSULTING_MENU";
    s.temp.selectedProductId = product.id;

    return responseWithAI(
      chatId,
      buildProductQuestionAIPrompt(product, msg),
      productActionMarkup(product.id),
      s,
      callbackQueryId
    );
