}

// 2) Product-only request: ask skin type first
if (
  !orderSteps.includes(s.step) &&
  !isCallbackCommand &&
  isProductOnlyRequest(msg)
) {
  s.step = "WAITING_PRODUCT_SKIN_TYPE";
  s.temp.pendingProductRequest = msg;

  return response(
    chatId,
    productTypeClarificationText(msg),
    backToConsultingMarkup(),
    s,
    callbackQueryId
  );
}

// 3) Answer to product skin type question
if (s.step === "WAITING_PRODUCT_SKIN_TYPE") {
  const answer = normalizeText(msg);
  const originalRequest = s.temp.pendingProductRequest || "";

  let skinText = "";

  if (answer.includes("1") || answer.includes("چرب") || answer.includes("مختلط")) {
    skinText = "پوست چرب یا مختلط";
