    skinText = "پوست خشک یا نرمال";
  } else if (answer.includes("3") || answer.includes("حساس")) {
    skinText = "پوست حساس";
  } else if (answer.includes("4") || answer.includes("نمیدونم") || answer.includes("نمی دونم")) {
    return response(
      chatId,
      `اشکالی نداره 🌸
برای تست دمو، یکی از این گزینه‌ها رو انتخاب کن:

1. پوستم زود چرب و براق میشه
2. پوستم کشیده و خشک میشه
3. پوستم سریع قرمز یا حساس میشه`,
      backToConsultingMarkup(),
      s,
      callbackQueryId
    );
  }

  if (!skinText) {
    return response(
      chatId,
      `لطفاً یکی از گزینه‌ها رو بفرست:

1. چرب یا مختلط
2. خشک یا نرمال
3. حساس
4. نمی‌دونم`,
      backToConsultingMarkup(),
      s,
      callbackQueryId
    );
  }

  const finalQuery = `${originalRequest} ${skinText}`;
  const found = findProductsByQuery(finalQuery);
  const product = found[0];

  if (product) {
    s.step = "CONSULTING_MENU";
    s.temp.selectedProductId = product.id;
    s.temp.lastSuggestedProductId = product.id;

    return responseWithAI(
      chatId,
      buildProductInfoAIPrompt(product, finalQuery, false),
      productActionMarkup(product.id),
      s,
      callbackQueryId
    );
  }

  s.step = "CONSULTING_MENU";

  return response(
    chatId,
    `برای این ترکیب، محصول دقیقی در لیست تستی پیدا نکردم 🌸
می‌تونی از بخش مشاوره خرید، مسیر نوع پوست یا مشکل پوستی رو انتخاب کنی.`,
    consultingMenuMarkup(),
    s,
    callbackQueryId
  );
}

// 4) Answer to vague beauty need
if (s.step === "WAITING_BEAUTY_NEED") {
  const userNeed = normalizeText(msg);
  let mappedNeed = "";

  if (userNeed.includes("1") || userNeed.includes("جوش") || userNeed.includes("چربی") || userNeed.includes("چرب")) {
    mappedNeed = "جوش و آکنه";
  } else if (userNeed.includes("2") || userNeed.includes("خشکی") || userNeed.includes("خشک") || userNeed.includes("حساس")) {
    mappedNeed = "خشکی پوست";
  } else if (userNeed.includes("3") || userNeed.includes("لک") || userNeed.includes("تیرگی")) {
    mappedNeed = "لک و تیرگی";
  } else if (
    userNeed.includes("4") ||
    userNeed.includes("ضدآفتاب") ||
    userNeed.includes("ضد افتاب") ||
    userNeed.includes("آبرسان") ||
    userNeed.includes("شوینده") ||
    userNeed.includes("ژل") ||
    userNeed.includes("تونر") ||
    userNeed.includes("سرم")
  ) {
    s.step = "WAITING_PRODUCT_SKIN_TYPE";
    s.temp.pendingProductRequest = msg;

    return response(
      chatId,
      productTypeClarificationText(msg),
      backToConsultingMarkup(),
      s,
      callbackQueryId
    );
  }

  if (mappedNeed) {
    const matched = findProductsByProblem(mappedNeed).slice(0, 3);
    s.step = "CONSULTING_MENU";

    if (matched.length > 0) {
      s.temp.lastSuggestedProductId = matched[0].id;
      s.temp.selectedProductId = matched[0].id;

      return responseWithAI(
        chatId,
        buildSkinProblemAdviceAIPrompt(mappedNeed, matched),
        backToConsultingMarkup(),
        s,
        callbackQueryId
      );
    }
  }

  return response(chatId, guidedNeedText(), backToConsultingMarkup(), s, callbackQueryId);
}

// 5) Free consultation
if (!orderSteps.includes(s.step) && !isCallbackCommand && isFreeConsultationMessage(msg)) {
  if (isVagueBeautyMessage(msg)) {
    s.step = "WAITING_BEAUTY_NEED";
    s.temp.freeConsultation = msg;

    return response(chatId, guidedNeedText(), backToConsultingMarkup(), s, callbackQueryId);
  }

  const matched = findNearestProducts(msg, 3);

  if (matched.length > 0) {
    s.step = "CONSULTING_MENU";
    s.temp.freeConsultation = msg;
    s.temp.lastSuggestedProductId = matched[0].id;
    s.temp.selectedProductId = matched[0].id;

    return responseWithAI(
      chatId,
      buildFreeConsultationAIPrompt(msg, matched),
      backToConsultingMarkup(),
      s,
      callbackQueryId
    );
  }

  s.step = "WAITING_BEAUTY_NEED";
  s.temp.freeConsultation = msg;

  return response(chatId, guidedNeedText(), backToConsultingMarkup(), s, callbackQueryId);
}

// 6) Direct product search
const directProductSearch = findProductsByQuery(msg);

if (
  directProductSearch.length > 0 &&
  !orderSteps.includes(s.step) &&
  !isCallbackCommand
) {
  const product = directProductSearch[0];

  s.step = "CONSULTING_MENU";
  s.temp.selectedProductId = product.id;
  s.temp.lastSuggestedProductId = product.id;

  return responseWithAI(
    chatId,
    buildProductInfoAIPrompt(product, msg, false),
    productActionMarkup(product.id),
    s,
    callbackQueryId
  );
}

// ============================================
// Fallback
// ============================================

return response(
  chatId,
  `متوجه منظورت نشدم 🌸
می‌تونی از منوی زیر یکی از گزینه‌ها رو انتخاب کنی یا اسم محصول/نیازت رو واضح‌تر بنویسی.

مثلاً:
ضدآفتاب پوست چرب
آبرسان پوست خشک
پوستم جوش می‌زنه`,
  mainMenuMarkup(),
  s,
  callbackQueryId
);

const aiText =
  $json.text ||
  $json.output ||
  $json.response ||
  $json.result ||
  $json.message ||
  $json.data ||
  "";

const original = $('Code in JavaScript').first().json;

return [
  {
    json: {
      chatId: original.chatId,
      text: String(aiText || "متأسفم، الان نتونستم پاسخ مشاوره‌ای تولید کنم. لطفاً دوباره امتحان کن.").trim(),
      replyMarkup: original.replyMarkup,
      session: original.session,
      callbackQueryId: original.callbackQueryId,
      aiRaw: $json
    }
  }
];

const update = $json || {};

// بعضی نودها خروجی را مستقیم می‌دهند، بعضی داخل body یا data
const raw = update.body || update.data || update;

// گرفتن chatId از حالت‌های مختلف احتمالی
const chatId =
  raw.chatId ||
  raw.chat_id ||
  raw.message?.chat?.id ||
  raw.message?.from?.id ||
  raw.callback_query?.message?.chat?.id ||
  raw.callbackQuery?.message?.chat?.id ||
  raw.callback_query?.from?.id ||
  raw.callbackQuery?.from?.id ||
  raw.chat?.id ||
  raw.from?.id ||
  raw.sender?.id ||
  null;

// گرفتن callbackQueryId
const callbackQueryId =
  raw.callback_query?.id ||
  raw.callbackQuery?.id ||
  null;

// گرفتن متن یا callback data
let msg = String(
  raw.text ??
  raw.message?.text ??
  raw.message?.caption ??
  raw.callback_query?.data ??
  raw.callbackQuery?.data ??
  raw.data ??
  ""
).trim();

// اگر کاربر برای اولین بار Start زده ولی متن خالی رسیده، آن را مثل /start حساب کن
if (!msg && chatId) {
  msg = "/start";
}

// بعضی وقت‌ها بله ممکنه متن شروع را فارسی بفرستد
if (msg === "شروع" || msg === "Start" || msg === "start") {
  msg = "/start";
}

return [
  {
    json: {
      update: raw,
      chatId,
      userKey: chatId ? String(chatId) : "",
      msg,
      callbackQueryId
    }
  }
];

const original = $('Code in JavaScript').first().json;

return [
  {
    json: original
  }
];

const normalized = $('Code - Normalize Input').first().json;
const row = $json || {};

let savedSession = null;

// اگر Data Table رکورد پیدا کرده باشد
if (row.session) {
  savedSession = row.session;
}

// اگر session به صورت متن ذخیره شده باشد
if (typeof savedSession === "string") {
  try {
    savedSession = JSON.parse(savedSession);
  } catch (e) {
    savedSession = null;
  }
}

return [
  {
    json: {
      update: normalized.update,
      chatId: normalized.chatId,
      userKey: normalized.userKey,
      msg: normalized.msg,
      callbackQueryId: normalized.callbackQueryId,
      session: savedSession
    }
  }
];
